"""Command line interface for wordstat."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

from wordstat import core


def _positive_int(value: str) -> int:
    try:
        n = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError("must be an integer >= 1")
    if n < 1:
        raise argparse.ArgumentTypeError("must be an integer >= 1")
    return n


def main(argv=None) -> int:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    if hasattr(sys.stderr, "reconfigure"):
        sys.stderr.reconfigure(encoding="utf-8", newline="\n", errors="backslashreplace")

    parser = argparse.ArgumentParser(prog="wordstat", allow_abbrev=False)
    parser.add_argument("file")
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--top", type=_positive_int, default=3)
    args = parser.parse_args(argv)

    try:
        try:
            data = Path(args.file).read_bytes()
        except OSError:
            sys.stderr.write("wordstat: error: %s: cannot read file\n" % args.file)
            return 3
        try:
            text = data.decode("utf-8-sig")
        except UnicodeDecodeError:
            sys.stderr.write("wordstat: error: %s: not valid UTF-8\n" % args.file)
            return 3
        result = core.analyze(text, args.top)
        out = core.format_json(result) if args.json else core.format_text(result)
    except Exception as exc:
        sys.stderr.write("wordstat: error: internal error: %s\n" % type(exc).__name__)
        return 1
    sys.stdout.write(out)
    return 0

